}

app taskvault {
  wasp: {
    version: "^0.16.0"
  },
  title: "TaskVault",
  server: {
    setupFn: import { setupServer } from "@src/serverSetup"
  }
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

query getTasks {
  fn: import { getTasks } from "@src/queries",
  entities: [Task]
}

action createTask {
  fn: import { createTask } from "@src/actions",
  entities: [Task]
}

api getStats {
  fn: import { getStats } from "@src/apis",
  httpRoute: (GET, "/api/stats"),
  entities: [Task]
}

job myStartupJob {
  executor: PgBoss,
  perform: {
    fn: import { runStartupJob } from "@src/jobs/startupJob"
  },
  entities: [EventLog]
}

export const runStartupJob = async (args, context) => {
  console.log("Running startup job...")
  await context.entities.EventLog.create({
    data: {
      message: "Startup job executed successfully."
    }
  })
  console.log("Startup job finished.")
}

import { myStartupJob } from 'wasp/server/jobs'

export const setupServer = async () => {
  console.log("Server is starting up, submitting startup job...")
  try {
    await myStartupJob.submit()
    console.log("Startup job submitted successfully!")
  } catch (err) {
    console.error("Failed to submit startup job:", err)
  }
}
